using System.Text;
using System.Text.RegularExpressions;

namespace Ark.Feedback.Analysis;

/// <summary>A comment, pre-processed once so every lexicon can look it up cheaply.</summary>
public sealed class CommentText
{
    public CommentText(string text)
    {
        Raw = text;
        Lower = text.ToLowerInvariant();
        var sb = new StringBuilder(Lower.Length + 2);
        sb.Append(' ');
        foreach (var r in Lower.EnumerateRunes())
        {
            var cat = Rune.GetUnicodeCategory(r);
            if (cat is System.Globalization.UnicodeCategory.UppercaseLetter or System.Globalization.UnicodeCategory.LowercaseLetter or System.Globalization.UnicodeCategory.OtherLetter
                or System.Globalization.UnicodeCategory.ModifierLetter or System.Globalization.UnicodeCategory.TitlecaseLetter or System.Globalization.UnicodeCategory.NonSpacingMark
                or System.Globalization.UnicodeCategory.SpacingCombiningMark or System.Globalization.UnicodeCategory.DecimalDigitNumber || r.Value is '\'' or '’' or '*' or '+')
                sb.Append(r.ToString());
            else if (sb[^1] != ' ') sb.Append(' ');
        }
        if (sb[^1] != ' ') sb.Append(' ');
        Norm = sb.ToString();
        Tokens = new HashSet<string>(Norm.Split(' ', StringSplitOptions.RemoveEmptyEntries), StringComparer.Ordinal);
    }

    public string Raw { get; }
    public string Lower { get; }
    /// <summary>Lower-cased, punctuation turned into single spaces, padded with a space on both ends: " like this ".</summary>
    public string Norm { get; }
    public HashSet<string> Tokens { get; }

    public bool HasPhrase(string phrase) => Norm.Contains(" " + phrase + " ", StringComparison.Ordinal);
}

/// <summary>A list of words and phrases; single words are looked up in the token set, phrases (and scripts without spaces) by substring.</summary>
public sealed class Lexicon
{
    private readonly HashSet<string> _words = new(StringComparer.Ordinal);
    private readonly List<string> _phrases = [];
    private readonly List<string> _raw = [];

    public Lexicon(params string[] terms)
    {
        foreach (var t0 in terms)
        {
            var t = t0.Trim().ToLowerInvariant();
            if (t.Length == 0) continue;
            if (IsSpaceless(t)) _raw.Add(t);
            else if (t.Contains(' ')) _phrases.Add(t);
            else _words.Add(t);
        }
    }

    public int Count => _words.Count + _phrases.Count + _raw.Count;

    /// <summary>CJK, Thai, Lao, Khmer, Burmese, Tibetan: no word boundaries, match anywhere.</summary>
    private static bool IsSpaceless(string t)
    {
        foreach (var r in t.EnumerateRunes())
        {
            var cp = r.Value;
            if (cp is >= 0x0E00 and <= 0x0EFF or >= 0x0F00 and <= 0x0FFF or >= 0x1000 and <= 0x109F or >= 0x1780 and <= 0x17FF or >= 0x3040 and <= 0x30FF or >= 0x3400 and <= 0x9FFF or >= 0xAC00 and <= 0xD7AF or >= 0xF900 and <= 0xFAFF) return true;
        }
        return false;
    }

    /// <summary>Distinct terms of this lexicon found in the comment.</summary>
    public List<string> Match(CommentText c)
    {
        List<string>? hits = null;
        foreach (var t in c.Tokens) if (_words.Contains(t)) (hits ??= []).Add(t);
        foreach (var p in _phrases) if (c.HasPhrase(p)) (hits ??= []).Add(p);
        foreach (var r in _raw) if (c.Lower.Contains(r, StringComparison.Ordinal)) (hits ??= []).Add(r);
        return hits ?? [];
    }

    public bool Any(CommentText c)
    {
        foreach (var t in c.Tokens) if (_words.Contains(t)) return true;
        foreach (var p in _phrases) if (c.HasPhrase(p)) return true;
        foreach (var r in _raw) if (c.Lower.Contains(r, StringComparison.Ordinal)) return true;
        return false;
    }
}

